package ltnc.auction.common.model;
import java.io.Serializable; import java.math.BigDecimal; import java.time.Instant; import java.util.ArrayList; import java.util.List;
public final class Auction implements Serializable { private static final long serialVersionUID=1L; private final String id; private final Item item; private final BigDecimal startingPrice, increment; private final Instant startAt,endAt; private AuctionStatus status; private BigDecimal highestPrice; private String highestBidderId; private final List<Bid> bids=new ArrayList<>();
 public Auction(String id,Item item,BigDecimal startingPrice,BigDecimal increment,Instant startAt,Instant endAt){if(startingPrice.signum()<0||increment.signum()<=0||!endAt.isAfter(startAt))throw new IllegalArgumentException("Thông tin phiên đấu giá không hợp lệ");this.id=id;this.item=item;this.startingPrice=startingPrice;this.increment=increment;this.startAt=startAt;this.endAt=endAt;this.status=AuctionStatus.OPEN;this.highestPrice=startingPrice;}
 public String getId(){return id;} public Item getItem(){return item;} public BigDecimal getStartingPrice(){return startingPrice;} public BigDecimal getIncrement(){return increment;} public Instant getStartAt(){return startAt;} public Instant getEndAt(){return endAt;} public synchronized AuctionStatus getStatus(){return status;} public synchronized void setStatus(AuctionStatus s){status=s;} public synchronized BigDecimal getHighestPrice(){return highestPrice;} public synchronized String getHighestBidderId(){return highestBidderId;} public synchronized List<Bid> getBids(){return List.copyOf(bids);} public synchronized void addBid(Bid bid){bids.add(bid);highestPrice=bid.getAmount();highestBidderId=bid.getBidderId();}
}
